  const warlordVfxCursor = {};
  function pickWarlordVfxVariation(warlordId, forcedIdx = null) {
    const list = WARLORD_VFX_VARIATIONS[warlordId] || WARLORD_VFX_VARIATIONS.zhuge;
    if (typeof forcedIdx === 'number' && forcedIdx >= 0) {
      return { variation: list[forcedIdx % list.length], idx: forcedIdx % list.length };
    }
    const prev = warlordVfxCursor[warlordId] ?? -1;
    // 이전과 다른 새로운 이펙트 조합이 나오도록 순환 + 랜덤 스텝
    const step = 1 + Math.floor(Math.random() * Math.max(1, list.length - 1));
    const idx = (prev + step) % list.length;
    warlordVfxCursor[warlordId] = idx;
    return { variation: list[idx], idx };
  }

  const loadedVfxCache = {};
  function getWarlordVfxObj(key) {
    if (loadedVfxCache[key]) return loadedVfxCache[key];
    const info = WARLORD_ATTACHED_VFX[key];
    if (!info) return null;
    const im = new Image();
    im.src = info.data;
    loadedVfxCache[key] = { im, fw: info.fw, fh: info.fh, frames: info.frames };
    return loadedVfxCache[key];
  }
  Object.keys(WARLORD_ATTACHED_VFX).forEach(getWarlordVfxObj);

